msg.topic = 'CREATE TABLE IF NOT EXISTS event_types (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT UNIQUE NOT NULL,
  description TEXT
);'; return msg;

let plate = msg.payload;
if (typeof plate === 'object' && plate.plate) plate = plate.plate;
plate = String(plate).trim().toUpperCase();
if (!plate || plate.length < 2) { node.warn('Ungueltig: ' + plate); return null; }
const lockKey = 'entry_lock_' + plate;
const lastSeen = flow.get(lockKey) || 0;
const now = Date.now();
if (now - lastSeen < 20000) {
  node.warn('Sperrfenster aktiv fuer: ' + plate);
  return null;
}
flow.set(lockKey, now);
msg.plate = plate;
msg.topic = 'SELECT id FROM parking_sessions WHERE plate = \'' + plate + '\' AND exit_time IS NULL LIMIT 1;';
return msg;

const rows = msg.payload;
const plate = msg.plate;
if (Array.isArray(rows) && rows.length > 0) {
  node.warn('Offene Session fuer ' + plate + ' – Einfahrt blockiert');
  msg.payload = JSON.stringify({ status: 'denied', display_text: plate + ' bereits im Parkhaus' });
  msg.topic = 'einfahren/status';
  return [null, msg];
}
return [msg, null];

const plate = msg.plate;
msg.topic = 'INSERT INTO parking_sessions (plate, entry_time, amount_due, amount_paid) VALUES (\'' + plate + '\', datetime(\'now\'), 0, 0);';
return msg;

const rows = msg.payload;
const plate = msg.plate;
if (!Array.isArray(rows) || rows.length === 0) {
  node.error('Session nicht gefunden nach INSERT fuer: ' + plate);
  return null;
}
const session = rows[0];
msg.session_id = session.id;
node.warn('Session gefunden: id=' + session.id + ' plate=' + plate);
msg.topic = 'INSERT INTO event_logs (eventtype, source, message, parking_session_id)\nVALUES (\'ENTRY_PLATE_DETECTED\', \'camera_entry\',\n  \'Kennzeichen ' + plate + ' bei Einfahrt erkannt\', ' + session.id + ');';
return msg;

const plate = msg.plate;
const sessionId = msg.session_id;
if (!sessionId) {
  node.error('Keine session_id fuer ENTRY_BARRIER_OPENED: ' + plate);
  return null;
}
node.warn('Einfahrt OK: Session=' + sessionId + ' Plate=' + plate);
msg._entry_response = JSON.stringify({ status: 'allowed', display_text: 'Willkommen ' + plate });
msg.topic = 'INSERT INTO event_logs (eventtype, source, message, parking_session_id)\nVALUES (\'ENTRY_BARRIER_OPENED\', \'node-red\',\n  \'Einfahrtsschranke fuer ' + plate + ' geoeffnet (Session ' + sessionId + ')\', ' + sessionId + ');';
return msg;

let plate = msg.payload;
if (typeof plate === 'object' && plate.plate) plate = plate.plate;
plate = String(plate).trim().toUpperCase();
msg.plate = plate;

// 20s Sperrfenster – identisch wie Einfahrt
const lockKey = 'exit_lock_' + plate;
const lastSeen = flow.get(lockKey) || 0;
if (Date.now() - lastSeen < 20000) {
  node.warn('Ausfahrt Sperrfenster aktiv fuer: ' + plate);
  return null;
}
flow.set(lockKey, Date.now());

node.warn('Ausfahrt: ' + plate);
msg.topic = 'SELECT id, plate, amount_due, amount_paid, payment_time, exit_valid_until, entry_time\nFROM parking_sessions\nWHERE plate = \'' + plate + '\' AND exit_time IS NULL\nORDER BY id DESC LIMIT 1;';
return msg;

const rows = msg.payload;
const plate = msg.plate;
const sessionId = (Array.isArray(rows) && rows.length > 0) ? rows[0].id : null;
const sessionIdSql = sessionId !== null ? String(sessionId) : 'NULL';
msg._rows = rows;
msg.topic = 'INSERT INTO event_logs (eventtype, source, message, parking_session_id)\n' +
  'VALUES (\'EXIT_PLATE_DETECTED\', \'camera_exit\',\n' +
  '  \'Kennzeichen ' + plate + ' bei Ausfahrt erkannt\', ' + sessionIdSql + ');';
return msg;

const rows = msg._rows;
const plate = msg.plate;

if (!Array.isArray(rows) || rows.length === 0) {
  msg._open_plate = plate;
  msg._open_session = null;
  msg._open_display = plate + ' – keine aktive Session gefunden';
  msg.payload = { command: 'deny', reason: 'no_active_session' };
  return msg;
}

const session = rows[0];
msg._open_plate = session.plate;
msg._open_session = session.id;

// Nur exit_valid_until prüfen
let withinWindow = false;
if (session.exit_valid_until) {
  // exit_valid_until wird vom REST-Backend als UTC-ISO-String geschrieben (.toISOString());
  // falls kein 'T' enthalten ist (z.B. SQLite datetime() ohne 'T'), als UTC interpretieren.
  const raw = session.exit_valid_until;
  const validUntil = new Date(raw.includes('T') ? raw : raw.replace(' ', 'T') + 'Z');
  withinWindow = validUntil > new Date();
}

node.warn('Ausfahrt: plate=' + plate + ' exit_valid_until=' + session.exit_valid_until + ' withinWindow=' + withinWindow);

if (withinWindow) {
  msg._open_display = 'Gute Fahrt ' + session.plate + '!';
  msg.payload = { command: 'open', reason: 'exit_valid' };
} else {
  msg._open_display = plate + ' – RFID-Chip halten (30s)';
  msg.payload = { command: 'deny', reason: 'no_valid_exit' };
}
return msg;

const sessionId = msg._open_session;
const plate = msg._open_plate;
const display = msg._open_display || 'Gute Fahrt!';

if (!sessionId) {
  node.warn('Keine session_id – SET exit_time uebersprungen');
  return null;
}

msg.plate = plate;
msg.session_id = sessionId;
msg._display = display;

if (msg._via_rfid) {
  // exit_time wurde bereits von sq_rfid_update_exit gesetzt – UPDATE ueberspringen
  node.log('SET exit_time: RFID-Pfad – UPDATE wird uebersprungen');
  msg.topic = 'SELECT 1;'; // Dummy damit sqlite-Node nicht leer laeuft
  return msg;
}

msg.topic = 'UPDATE parking_sessions SET exit_time = datetime(\'now\') WHERE id = ' + sessionId + ';';
return msg;

const plate = msg.plate; const sid = msg.session_id;
msg.topic = 'INSERT INTO event_logs (eventtype, source, message, parking_session_id) VALUES (\'EXIT_BARRIER_OPENED\', \'node-red\', \'Ausfahrtsschranke fuer ' + plate + ' geoeffnet (Session ' + sid + ')\', ' + sid + ');';
return msg;

msg.payload = JSON.stringify({
  status: 'allowed',
  display_text: msg._open_display || 'Gute Fahrt!'
});
msg.topic = 'ausfahren/status';
return msg;

const plate = msg._open_plate || msg.plate;
const sessionId = msg._open_session;
const sessionIdSql = sessionId != null ? sessionId : 'NULL';
const displayText = msg._open_display || plate + ' – RFID-Chip halten (30s)';
const reason = msg.payload && msg.payload.reason ? msg.payload.reason : 'no_valid_exit';

flow.set('pending_rfid_plate', plate);
flow.set('pending_rfid_session', sessionId);
flow.set('rfid_window_open', true);
node.warn('Ausfahrt verweigert: ' + plate + ' Session=' + sessionId + ' → RFID-Fenster OFFEN (30s)');

msg.plate = plate;
msg.session_id = sessionId;
msg.topic = 'INSERT INTO event_logs (eventtype, source, message, parking_session_id)\nVALUES (\'EXIT_BARRIER_DENIED\', \'node-red\',\n  \'Ausfahrt fuer ' + plate + ' verweigert (' + reason + ')\', ' + sessionIdSql + ');';
msg._deny_display = displayText;
return msg;

const displayText = msg._deny_display || (msg.plate ? msg.plate + ' – Ausfahrt verweigert' : 'Ausfahrt verweigert');
msg.payload = JSON.stringify({ status: 'denied', display_text: displayText });
msg.topic = 'ausfahren/status';
return msg;

const windowOpen = flow.get('rfid_window_open') || false;
if (!windowOpen) {
  node.log('RFID-Timeout: Fenster bereits geschlossen – kein Cleanup noetig');
  return null;
}
const plate = flow.get('pending_rfid_plate');
flow.set('rfid_window_open', false);
flow.set('pending_rfid_plate', null);
flow.set('pending_rfid_session', null);
node.warn('RFID-Fenster GESCHLOSSEN per Timeout' + (plate ? ' fuer: ' + plate : ''));
return null;

let uid = msg.payload;
if (typeof uid === 'object' && uid.uid) uid = uid.uid;
uid = String(uid).trim();

const windowOpen = flow.get('rfid_window_open') || false;
const plate = flow.get('pending_rfid_plate') || null;
const sessionId = flow.get('pending_rfid_session') || null;

node.warn('RFID: UID=' + uid + ' window_open=' + windowOpen + ' plate=' + plate);

// Immer Admin-Lookup – Entscheidung kommt danach
msg.rfid_uid = uid;
msg._rfid_window_open = windowOpen;
msg._rfid_plate = plate;
msg._rfid_session = sessionId;
msg.topic = 'SELECT id, name, role FROM user_admins WHERE rfid_uid = \'' + uid + '\' AND active = 1 LIMIT 1;';
return msg;

const rows = msg.payload;
const uid = msg.rfid_uid;

if (!Array.isArray(rows) || rows.length === 0) {
  node.warn('RFID unbekannt: ' + uid);
  msg.topic = 'INSERT INTO event_logs (eventtype, source, message, parking_session_id)\nVALUES (\'UNKNOWN_RFID\', \'rfid_exit\',\n  \'Unbekannter RFID ' + uid + '\', NULL);';
  msg._rfid_display = 'RFID unbekannt – keine Freigabe';
  return [null, msg];
}

const admin = rows[0];
msg.admin_id = admin.id;
msg.admin_name = admin.name;
node.log('RFID Admin bekannt: ' + admin.name);
return [msg, null];

const plate = msg.plate;
const sid = msg.session_id;
const uid = msg.rfid_uid;
const admin = msg.admin_name;
msg._open_plate = plate;
msg._open_session = sid;
msg._open_display = 'RFID-Freigabe erteilt – Gute Fahrt ' + plate + '!';
msg.topic = 'INSERT INTO event_logs (eventtype, source, message, parking_session_id)\nVALUES (\'RFID_ADMIN_RELEASE\', \'rfid_exit\',\n  \'Admin-Freigabe per RFID fuer ' + plate + ' durch ' + admin + ' (UID: ' + uid + ')\', ' + sid + ');';
flow.set('rfid_window_open', false);
flow.set('pending_rfid_plate', null);
flow.set('pending_rfid_session', null);
node.log('RFID-Fenster GESCHLOSSEN nach Freigabe fuer: ' + plate);
return msg;

let data = msg.payload;
if (typeof data === 'string') { try { data = JSON.parse(data); } catch (e) { node.error('Invalid JSON', msg); return null; } }
if (typeof data !== 'object' || data === null) { node.error('Payload muss Objekt sein', msg); return null; }
const spotId = Number(data.id ?? data.spot_id);
if (!Number.isInteger(spotId) || spotId <= 0) { node.error('Ungueltige spot id', msg); return null; }
const rawStatus = String(data.status ?? '').trim().toLowerCase();
if (!['occupied', 'free'].includes(rawStatus)) { node.error('status muss occupied oder free sein', msg); return null; }
msg.spot_id = spotId;
msg.occupied = rawStatus === 'occupied' ? 1 : 0;
msg.event_message = 'Parking spot ' + spotId + ' is now ' + rawStatus;
msg.topic = 'UPDATE parking_spots SET occupied = ' + msg.occupied + ', last_updated = datetime(\'now\') WHERE id = ' + spotId + ';';
return msg;

let data = msg.payload;
if (typeof data === 'string') { try { data = JSON.parse(data); } catch (e) { node.error('Invalid JSON', msg); return null; } }
const floor = Number(data.floor);
const status = String(data.status ?? '').trim().toLowerCase();
if (![1, 2].includes(floor)) { node.error('floor muss 1 oder 2 sein', msg); return null; }
if (!['on', 'off'].includes(status)) { node.error('status muss on oder off sein', msg); return null; }
const eventType = status === 'on' ? 'LIGHT_TURNED_ON' : 'LIGHT_TURNED_OFF';
const source = 'motion_sensor_floor_' + floor;
const message = 'Etage ' + floor + ': Licht ' + status;
msg.topic = 'INSERT INTO event_logs (eventtype, source, message, parking_session_id) VALUES (\'' + eventType + '\', \'' + source + '\', \'' + message + '\', NULL);';
return msg;

msg._total_spots = msg.payload[0].total_spots;
msg.topic = 'SELECT COUNT(*) as active_sessions FROM parking_sessions WHERE exit_time IS NULL;';
return msg;

const totalSpots = msg._total_spots || 0;
const activeSessions = msg.payload[0].active_sessions || 0;
const freeSpots = totalSpots - activeSessions;
const plate = msg.plate;

node.warn('Kapazitaet: total=' + totalSpots + ' aktiv=' + activeSessions + ' frei=' + freeSpots);

if (freeSpots <= 0) {
  msg.payload = JSON.stringify({ status: 'denied', display_text: 'Parkhaus voll – keine freien Plaetze' });
  msg.topic = 'einfahren/status';
  return [null, msg];
}
return [msg, null];

msg.payload = {
  command: 'open',
  plate: msg._open_plate,
  session_id: msg._open_session,
  display_text: msg._open_display
};
msg._via_rfid = true;
return msg;

const windowOpen = msg._rfid_window_open;
const plate = msg._rfid_plate;
const sessionId = msg._rfid_session;

if (windowOpen && plate && sessionId) {
  // 30s-Fenster aktiv → Session beenden wie bisher
  node.log('RFID mit Session: ' + plate + ' Session=' + sessionId);
  msg.plate = plate;
  msg.session_id = sessionId;
  msg.topic = 'UPDATE parking_sessions SET exit_time = datetime(\'now\') WHERE id = ' + sessionId + ';';
  return [msg, null];
} else {
  // Kein offener Vorgang → Schranke direkt auf, keine Session beenden
  node.log('RFID ohne Session – direkte Admin-Freigabe');
  return [null, msg];
}

const uid = msg.rfid_uid;
const admin = msg.admin_name;
msg._open_plate = null;
msg._open_session = null;
msg._open_display = 'Admin-Freigabe: ' + admin;
node.warn('RFID direkte Admin-Freigabe: ' + admin + ' (UID: ' + uid + ') – kein Fenster offen');
msg.topic = 'INSERT INTO event_logs (eventtype, source, message, parking_session_id)\nVALUES (\'RFID_ADMIN_RELEASE\', \'rfid_exit\',\n  \'Direkte Admin-Freigabe per RFID durch ' + admin + ' (UID: ' + uid + ') – keine aktive Session\', NULL);';
return msg;

node.log('RFID direkte Admin-Freigabe: ' + (msg._open_display || 'Admin-Freigabe'));
msg.payload = JSON.stringify({
  status: 'allowed',
  display_text: msg._open_display || 'Admin-Freigabe'
});
msg.topic = 'ausfahren/status';
return msg;
